    center = W // 2

    output = [[0] * W for _ in range(W)]

    # Main diagonal: r = c
    for r in range(W):
        if (r % 2 == 0 and r != center) or (r % 2 == 1):
            output[r][r] = 2
        else:
            output[r][r] = 0

    # Anti-diagonal: r + c = 2*center
    for r in range(W):
        c = 2*center - r
        if 0 <= c < W:
            if r % 2 == 0:
                output[r][c] = 2
            else:
                output[r][c] = 0

    # Set center to 0
    output[center][center] = 0

    # Fill remaining (between diagonals)
    for r in range(W):
        for c in range(W):
            if output[r][c] == 0 and not (r == c or r + c == 2*center):
                if (r + c) % 2 == (2*center) % 2:
                    # On the same parity "strips" as cross
                    if abs(r - center) + abs(c - center) == center:
                        output[r][c] = 1
                # else 0 (gap between X arms)

    return output

